3: /*
4:  * CPU accounting code for task groups.
5:  *
6:  * Based on the work by Paul Menage (menage@google.com) and Balbir Singh
7:  * (balbir@in.ibm.com).
8:  */
9: 
10: #ifdef CONFIG_BPF_RVI
11: #include <linux/bpf.h>
12: #include <linux/btf.h>
13: #include <linux/btf_ids.h>
14: #endif
15: 
16: /* Time spent by the tasks of the CPU accounting group executing in ... */
17: enum cpuacct_stat_index {
18: 	CPUACCT_STAT_USER,	/* ... user mode */
19: 	CPUACCT_STAT_SYSTEM,	/* ... kernel mode */
20: 
21: 	CPUACCT_STAT_NSTATS,
22: };
23: 
24: static const char * const cpuacct_stat_desc[] = {
25: 	[CPUACCT_STAT_USER] = "user",
26: 	[CPUACCT_STAT_SYSTEM] = "system",
27: };
28: 
29: /* track CPU usage of a group of tasks and its child groups */
30: struct cpuacct {
31: 	struct cgroup_subsys_state	css;
32: 	/* cpuusage holds pointer to a u64-type object on every CPU */
33: 	u64 __percpu	*cpuusage;
34: 	struct kernel_cpustat __percpu	*cpustat;
35: };
36: 
37: static inline struct cpuacct *css_ca(struct cgroup_subsys_state *css)
38: {
39: 	return css ? container_of(css, struct cpuacct, css) : NULL;
40: }
41: 
42: /* Return CPU accounting group to which this task belongs */
43: static inline struct cpuacct *task_ca(struct task_struct *tsk)
44: {
45: 	return css_ca(task_css(tsk, cpuacct_cgrp_id));
46: }
47: 
48: static inline struct cpuacct *parent_ca(struct cpuacct *ca)
49: {
50: 	return css_ca(ca->css.parent);
51: }
52: 
53: static DEFINE_PER_CPU(u64, root_cpuacct_cpuusage);
54: static struct cpuacct root_cpuacct = {
55: 	.cpustat	= &kernel_cpustat,
56: 	.cpuusage	= &root_cpuacct_cpuusage,
57: };
58: 
59: /* Create a new CPU accounting group */
60: static struct cgroup_subsys_state *
61: cpuacct_css_alloc(struct cgroup_subsys_state *parent_css)
62: {
63: 	struct cpuacct *ca;
64: 
65: 	if (!parent_css)
66: 		return &root_cpuacct.css;
67: 
68: 	ca = kzalloc(sizeof(*ca), GFP_KERNEL);
69: 	if (!ca)
70: 		goto out;
71: 
72: 	ca->cpuusage = alloc_percpu(u64);
73: 	if (!ca->cpuusage)
74: 		goto out_free_ca;
75: 
76: 	ca->cpustat = alloc_percpu(struct kernel_cpustat);
77: 	if (!ca->cpustat)
78: 		goto out_free_cpuusage;
79: 
80: 	return &ca->css;
81: 
82: out_free_cpuusage:
83: 	free_percpu(ca->cpuusage);
84: out_free_ca:
85: 	kfree(ca);
86: out:
87: 	return ERR_PTR(-ENOMEM);
88: }
89: 
90: /* Destroy an existing CPU accounting group */
91: static void cpuacct_css_free(struct cgroup_subsys_state *css)
92: {
93: 	struct cpuacct *ca = css_ca(css);
94: 
95: 	free_percpu(ca->cpustat);
96: 	free_percpu(ca->cpuusage);
97: 	kfree(ca);
98: }
