100: static u64 cpuacct_cpuusage_read(struct cpuacct *ca, int cpu,
101: 				 enum cpuacct_stat_index index)
102: {
103: 	u64 *cpuusage = per_cpu_ptr(ca->cpuusage, cpu);
104: 	u64 *cpustat = per_cpu_ptr(ca->cpustat, cpu)->cpustat;
105: 	u64 data;
106: 
107: 	/*
108: 	 * We allow index == CPUACCT_STAT_NSTATS here to read
109: 	 * the sum of usages.
110: 	 */
111: 	if (WARN_ON_ONCE(index > CPUACCT_STAT_NSTATS))
112: 		return 0;
113: 
114: #ifndef CONFIG_64BIT
115: 	/*
116: 	 * Take rq->lock to make 64-bit read safe on 32-bit platforms.
117: 	 */
118: 	raw_spin_rq_lock_irq(cpu_rq(cpu));
119: #endif
120: 
121: 	switch (index) {
122: 	case CPUACCT_STAT_USER:
123: 		data = cpustat[CPUTIME_USER] + cpustat[CPUTIME_NICE];
124: 		break;
125: 	case CPUACCT_STAT_SYSTEM:
126: 		data = cpustat[CPUTIME_SYSTEM] + cpustat[CPUTIME_IRQ] +
127: 			cpustat[CPUTIME_SOFTIRQ];
128: 		break;
129: 	case CPUACCT_STAT_NSTATS:
130: 		data = *cpuusage;
131: 		break;
132: 	}
133: 
134: #ifndef CONFIG_64BIT
135: 	raw_spin_rq_unlock_irq(cpu_rq(cpu));
136: #endif
137: 
138: 	return data;
139: }
140: 
141: static void cpuacct_cpuusage_write(struct cpuacct *ca, int cpu)
142: {
143: 	u64 *cpuusage = per_cpu_ptr(ca->cpuusage, cpu);
144: 	u64 *cpustat = per_cpu_ptr(ca->cpustat, cpu)->cpustat;
145: 
146: 	/* Don't allow to reset global kernel_cpustat */
147: 	if (ca == &root_cpuacct)
148: 		return;
149: 
150: #ifndef CONFIG_64BIT
151: 	/*
152: 	 * Take rq->lock to make 64-bit write safe on 32-bit platforms.
153: 	 */
154: 	raw_spin_rq_lock_irq(cpu_rq(cpu));
155: #endif
156: 	*cpuusage = 0;
157: 	cpustat[CPUTIME_USER] = cpustat[CPUTIME_NICE] = 0;
158: 	cpustat[CPUTIME_SYSTEM] = cpustat[CPUTIME_IRQ] = 0;
159: 	cpustat[CPUTIME_SOFTIRQ] = 0;
160: 
161: #ifndef CONFIG_64BIT
162: 	raw_spin_rq_unlock_irq(cpu_rq(cpu));
163: #endif
164: }
